import { inject, Injectable, InjectionToken, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { map, Observable, Subject } from 'rxjs';
import { injectGameAnalytics } from '../analytics/game-analytics';
import { GameAccount } from '../storage/game-account';
import { GameCloud } from '../storage/game-cloud';
import { type OpenRoom, normalizeRoomCode } from '../storage/game-rooms';
import { Lockstep } from './lockstep';
import {
  NET_VERSION,
  NetMessage,
  OnlineSetup,
  OnlineStart,
  parseNetMessage,
  agreedRuleset,
} from './net-message';
import { WebRtcTransport } from './peer-link';
import {
  type PeerConnection,
  type PeerTransport,
  PeerUnreachableError,
  type Relay,
  type UnreachableKind,
} from './peer-transport';
import { PlayerService } from '../state/player.service';
import type { Ruleset } from '@wolsok/feat-shared-bacteria-engine';
import { errorCode } from '../storage/retry';
import type { GameText } from '../i18n/game-texts';
import type { RelayServer } from '../storage/game-relay';

/** Where the lobby of an online match stands. */
export type OnlinePhase =
  /** Nothing under way. */
  | 'idle'
  /** The host opens a room. */
  | 'opening'
  /** The host waits for a guest to type the code in. */
  | 'waiting'
  /** The devices connect. */
  | 'connecting'
  /** Both devices are there - the host may start. */
  | 'connected';

/** The lobby as the player sees it. */
export interface OnlineLobby {
  phase: OnlinePhase;
  /** Who opened the room - null before anyone did. */
  role: 'host' | 'guest' | null;
  /** The room's code, for the host to pass on. */
  code: string | null;
  /**
   * What went wrong last, or why the other device left, as a text to
   * translate - null if nothing.
   */
  notice: GameText | null;
  /** True for a match the matchmaking set up: the host starts at once. */
  auto: boolean;
}

/** The room of an online match and its number there - with the seed, its replay's id. */
export interface OnlineMatchRef {
  roomCode: string;
  n: number;
}

/** Why an online connection ended. */
export type OnlineEnd = 'left' | 'lost';

/** What happens in an online match, for the game to follow. */
export type OnlineEvent =
  /** The other device is there. */
  | { type: 'connected'; seat: 0 | 1; auto: boolean }
  /** The guest's own colours - for the host, see `offerColors`. */
  | { type: 'colors'; colors: [string, string] }
  /** The host changed the next match's setup - for the guest. */
  | { type: 'setup'; setup: OnlineSetup }
  /** The host started a match - for the guest; see {@link takeStart}. */
  | { type: 'start'; start: OnlineStart }
  /** The connection is gone. */
  | { type: 'ended'; reason: OnlineEnd };

/**
 * The transport online matches connect over: WebRTC unless a spec provides
 * `pairedTransport()`. Declared here, beside the service that injects it,
 * so the bundle needs no import of Angular's of its own for it.
 */
export const PEER_TRANSPORT = new InjectionToken<PeerTransport>(
  'PeerTransport',
  { providedIn: 'root', factory: () => new WebRtcTransport() }
);

export const IDLE_LOBBY: OnlineLobby = {
  phase: 'idle',
  role: null,
  code: null,
  notice: null,
  auto: false,
};

/**
 * Online matches between two devices: the lobby - a room opened under a
 * code, joined by a guest - and then the connection, which carries the
 * setup, the start of each match and the lockstep's inputs.
 *
 * The host plays the left colony and sets the matches up; the guest plays
 * the right one and follows.
 */
@Injectable({ providedIn: 'root' })
export class OnlineMatchService {
  private readonly cloud = inject(GameCloud);
  /** The direct line to the other device - WebRTC in the game. */
  private readonly wire = inject(PEER_TRANSPORT);
  private readonly analytics = injectGameAnalytics();
  /** Who plays at this device - their uid goes to the other one. */
  private readonly playerId = toSignal(
    inject(GameAccount).players.pipe(map(({ playerId }) => playerId)),
    { initialValue: null }
  );
  private readonly peerState = signal<string | null>(null);
  private readonly players = inject(PlayerService);
  /**
   * The rulesets each device offered in its hello. Both sides settle the
   * ruleset on these, never on what this device would offer now - a
   * self-test verdict that came in after the hello changes nothing.
   */
  private ownOffers: readonly Ruleset[] = ['cpu'];
  private peerOffers: readonly Ruleset[] = ['cpu'];
  private readonly lobbyState = signal<OnlineLobby>(IDLE_LOBBY);
  private readonly events = new Subject<OnlineEvent>();
  private link: PeerConnection | null = null;
  private room: OpenRoom | null = null;
  /** The lockstep of the match under way, null before the first one. */
  private lockstep: Lockstep | null = null;
  /** The number of the match under way - inputs of another are dropped. */
  private match = 0;
  /** A start the host sent that the guest's game has not taken yet. */
  private pendingStart: { start: OnlineStart; lockstep: Lockstep } | null =
    null;
  /** True once the other device said hello in this version. */
  private greeted = false;
  /** Counts the attempts to connect, so a stale one gives up. */
  private attempt = 0;

  public readonly lobby = this.lobbyState.asReadonly();
  /**
   * The uid of the player at the other device once they said hello - kept
   * after the connection, so the result can offer to add them as a friend.
   */
  public readonly peer = this.peerState.asReadonly();
  public readonly events$: Observable<OnlineEvent> = this.events.asObservable();

  /** True where online matches can be played: with the cloud and WebRTC. */
  public get available(): boolean {
    return this.wire.supported() && this.cloud.rooms() !== null;
  }

  /**
   * Opens a room and waits for a guest. `onCode` hears the room's code as
   * soon as it is open - to challenge a friend with it, or hand it to a
   * player waiting in the matchmaking queue.
   */
  public async host(
    options: { auto?: boolean; onCode?: (code: string) => void } = {}
  ): Promise<void> {
    const rooms = this.cloud.rooms();
    if (rooms === null) {
      return;
    }
    const attempt = this.restart({
      phase: 'opening',
      role: 'host',
      auto: options.auto ?? false,
    });
    try {
      const relay = await this.relay();
      if (attempt !== this.attempt) {
        return;
      }
      const { link, offer } = await this.wire.offer(this.relayOf(relay));
      if (!this.adopt(link, attempt)) {
        return;
      }
      const room = await rooms.open(offer);
      if (attempt !== this.attempt) {
        room.close();
        return;
      }
      this.room = room;
      this.update({ phase: 'waiting', code: room.code });
      options.onCode?.(room.code);
      const answer = await room.answer;
      if (attempt !== this.attempt) {
        return;
      }
      this.update({ phase: 'connecting' });
      await link.accept(answer);
      await link.opened;
      // Taken: nobody else may join it, and the stub names who played -
      // what the functions bind the room's replays to (ADR 0011). The
      // match goes on without it; its uploads would be refused.
      this.room = null;
      if (attempt === this.attempt) {
        room.take().catch((error: unknown) => {
          console.warn('The room could not be taken', error);
        });
      }
    } catch (error) {
      this.fail(attempt, error);
    }
  }

  /** Joins the room under the code a player typed in. */
  public async join(
    typed: string,
    options: { auto?: boolean } = {}
  ): Promise<void> {
    const rooms = this.cloud.rooms();
    const code = normalizeRoomCode(typed);
    if (rooms === null) {
      return;
    }
    if (code === null) {
      this.update({ notice: { key: 'online.notices.badCode' } });
      return;
    }
    const attempt = this.restart({
      phase: 'connecting',
      role: 'guest',
      code,
      auto: options.auto ?? false,
    });
    // Read while the room is: both before the answer.
    const relay = this.relay();
    try {
      const room = await rooms.join(code);
      if (attempt !== this.attempt) {
        return;
      }
      if (room === null) {
        this.endWith(attempt, { key: 'online.notices.noRoom' });
        return;
      }
      const { link, answer } = await this.wire.answer(
        room.offer,
        this.relayOf(await relay)
      );
      if (!this.adopt(link, attempt)) {
        return;
      }
      await room.answer(answer);
      await link.opened;
    } catch (error) {
      if (errorCode(error) === 'permission-denied') {
        // Another guest answered the room first.
        this.endWith(attempt, { key: 'online.notices.taken' });
        return;
      }
      this.fail(attempt, error);
    }
  }

  /** Leaves the room or the match, telling the other device. */
  public leave(): void {
    this.send({ k: 'bye' });
    this.restart(IDLE_LOBBY);
  }

  /** The host shares the setup of the next match with the guest. */
  public share(setup: OnlineSetup): void {
    if (this.lobby().role === 'host') {
      this.send({ k: 'setup', ...setup });
    }
  }

  /**
   * The guest tells the host its own colours, which the host makes the
   * match's pair from. The guest plays the pair the host sends back.
   */
  public offerColors(colors: [string, string]): void {
    if (this.lobby().role === 'guest') {
      this.send({ k: 'colors', colors });
    }
  }

  /**
   * The host starts a match: tells the guest, and returns the lockstep to
   * play it with. Null while no guest is connected.
   */
  public startMatch(start: OnlineStart): Lockstep | null {
    if (this.lobby().role !== 'host' || this.lobby().phase !== 'connected') {
      return null;
    }
    this.match++;
    this.send({ k: 'start', n: this.match, ...start });
    this.lockstep = this.newLockstep(0);
    return this.lockstep;
  }

  /**
   * The ruleset the next match plays by: `gpu-int` when both devices
   * offered it in their hellos, `cpu` else (ADR 0015) - the host starts it,
   * the guest checks it. A device whose GPU failed since plays its
   * `gpu-int` matches on `intSimulation`, so the ruleset still holds.
   */
  public agreedRuleset(): Ruleset {
    return agreedRuleset(this.ownOffers, this.peerOffers);
  }

  /**
   * The room of the match under way and its number there - with the seed,
   * what its replay's id is made of (ADR 0011). Null before the first
   * match of a room.
   */
  public matchRef(): OnlineMatchRef | null {
    const { code } = this.lobby();
    return code === null || this.match === 0
      ? null
      : { roomCode: code, n: this.match };
  }

  /**
   * The guest's game takes the match the host started - null when none
   * waits.
   */
  public takeStart(): { start: OnlineStart; lockstep: Lockstep } | null {
    const pending = this.pendingStart;
    this.pendingStart = null;
    return pending;
  }

  /**
   * Lets go of whatever was under way and sets the lobby to `lobby` -
   * telling the game, for `reason`, if it was connected.
   */
  private restart(
    lobby: Partial<OnlineLobby>,
    reason: OnlineEnd = 'left'
  ): number {
    const wasConnected = this.greeted;
    this.attempt++;
    this.room?.close();
    this.room = null;
    const link = this.link;
    this.link = null;
    link?.close();
    this.lockstep = null;
    this.pendingStart = null;
    this.greeted = false;
    this.ownOffers = ['cpu'];
    this.peerOffers = ['cpu'];
    this.lobbyState.set({ ...IDLE_LOBBY, ...lobby });
    if (wasConnected) {
      this.events.next({ type: 'ended', reason });
    }
    return this.attempt;
  }

  /**
   * The TURN relay to connect through where the devices cannot reach each
   * other directly (ADR 0020) - none without its credentials.
   */
  private relay(): Promise<readonly RelayServer[]> {
    return this.cloud.relay()?.servers() ?? Promise.resolve([]);
  }

  /** The relay for a link: `servers` now, fresh ones while it lasts. */
  private relayOf(servers: readonly RelayServer[]): Relay {
    return { servers, fresh: () => this.relay() };
  }

  /** Takes the link of an attempt - false when the attempt is over. */
  private adopt(link: PeerConnection, attempt: number): boolean {
    if (attempt !== this.attempt) {
      link.close();
      return false;
    }
    this.link = link;
    let opened = false;
    link.messages$.subscribe((data) => this.receive(data));
    // Before it opened, the attempt hears why from `opened`'s rejection.
    link.closed$.subscribe(() => opened && this.onClosed(link));
    link.opened.then(
      () => {
        opened = true;
        this.ownOffers = [...this.players.rulesetOffers()];
        this.send({
          k: 'hello',
          v: NET_VERSION,
          id: this.playerId(),
          r: [...this.ownOffers],
        });
      },
      () => undefined
    );
    return true;
  }

  private receive(data: string): void {
    const message = parseNetMessage(data);
    if (message === null) {
      return;
    }
    if (message.k === 'hello') {
      this.peerState.set(message.id);
      this.peerOffers = message.r;
      this.greet(message.v);
      return;
    }
    if (!this.greeted) {
      return;
    }
    const { role } = this.lobby();
    switch (message.k) {
      case 'setup':
        if (role === 'guest') {
          this.events.next({ type: 'setup', setup: setupOf(message) });
        }
        return;
      case 'colors':
        if (role === 'host') {
          this.events.next({ type: 'colors', colors: message.colors });
        }
        return;
      case 'start':
        if (role === 'guest' && message.ruleset !== this.agreedRuleset()) {
          // A host that picks a ruleset both did not offer plays another game.
          this.endWith(this.attempt, { key: 'online.notices.otherVersion' });
          return;
        }
        if (role === 'guest') {
          this.match = message.n;
          this.lockstep = this.newLockstep(1);
          const start: OnlineStart = {
            ...setupOf(message),
            seed: message.seed,
            ruleset: message.ruleset,
          };
          this.pendingStart = { start, lockstep: this.lockstep };
          this.events.next({ type: 'start', start });
        }
        return;
      case 'in':
        if (message.n === this.match) {
          this.lockstep?.putRemote(message.t, message);
        }
        return;
      case 'sum':
        if (message.n === this.match) {
          this.lockstep?.putRemoteSum(message.t, message.h);
        }
        return;
      case 'bye':
        this.endWith(
          this.attempt,
          { key: 'online.notices.opponentLeft' },
          'left'
        );
        return;
    }
  }

  private greet(version: string): void {
    if (version !== NET_VERSION) {
      this.endWith(this.attempt, { key: 'online.notices.otherVersion' });
      return;
    }
    if (this.greeted) {
      return;
    }
    this.greeted = true;
    this.update({ phase: 'connected', notice: null });
    const { role, auto } = this.lobby();
    this.analytics.track('online_connected', {
      role: role ?? 'none',
      matchmade: auto,
    });
    this.events.next({
      type: 'connected',
      seat: role === 'host' ? 0 : 1,
      auto,
    });
  }

  private onClosed(link: PeerConnection): void {
    if (link === this.link) {
      this.endWith(this.attempt, { key: 'online.notices.lost' }, 'lost');
    }
  }

  private fail(attempt: number, error: unknown): void {
    console.warn('The online match could not connect', error);
    if (error instanceof PeerUnreachableError) {
      this.endWith(
        attempt,
        { key: 'online.notices.unreachable' },
        'lost',
        error.kind
      );
      return;
    }
    this.endWith(attempt, { key: 'online.notices.failed' });
  }

  /** Ends the attempt with a notice, telling the game if it was connected. */
  private endWith(
    attempt: number,
    notice: GameText,
    reason: OnlineEnd = 'lost',
    failure: UnreachableKind | 'none' = 'none'
  ): void {
    if (attempt !== this.attempt) {
      return;
    }
    this.analytics.track('online_ended', {
      reason,
      notice: notice.key,
      failure,
    });
    this.restart({ notice }, reason);
  }

  private newLockstep(seat: 0 | 1): Lockstep {
    const match = this.match;
    return new Lockstep(
      seat,
      (message) => {
        // A match that was replaced sends nothing more.
        if (match === this.match) {
          this.send(message);
        }
      },
      match
    );
  }

  private send(message: NetMessage): void {
    this.link?.send(JSON.stringify(message));
  }

  private update(change: Partial<OnlineLobby>): void {
    this.lobbyState.update((lobby) => ({ ...lobby, ...change }));
